export interface IncidentReviewIn {
  /** Who analyses it (the head of the unit, a senior clinician, the Quality Officer); never someone involved */
  investigator_user_id: number;
  /** Default: incident_analysis_days, or sentinel_analysis_days for a sentinel event */
  analysis_due?: string | null;
  /** Correct the type */
  type_code?: string | null;
  kind?: "Incident" | "NearMiss" | null;
  harm?: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death" | null;
  /** Only to decide otherwise than the list: with sentinel_reason */
  is_sentinel?: boolean | null;
  sentinel_reason?: string | null;
  /** The review note (e.g. what was corrected and why) */
  note?: string | null;
  expected_version?: number | null;
}

