/** The incident register — GET /api/v1/incidents (who may call: holders of incident.view or incident.report or ot.clinical_statistics.view). */
export function listIncidents(query?: { status?: "Reported" | "UnderReview" | "Analysed" | "Closed" | "Withdrawn" | null; type_code?: string | null; area?: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational" | null; sentinel_only?: boolean; harm?: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death" | null; department_id?: number | null; booking_id?: number | null; patient_id?: number | null; date_from?: string | null; date_to?: string | null; mine?: boolean; open_only?: boolean; limit?: number }): Promise<IncidentOut[]> {
  return api<IncidentOut[]>("GET", withQuery(`/incidents`, query), undefined);
}

/** One incident — GET /api/v1/incidents/{incident_id} (who may call: incident.view, the reporter and the investigator; ot.clinical_statistics.view for theatre adverse events). */
export function getIncident(incident_id: number): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("GET", `/incidents/${incident_id}`, undefined);
}

/** Review a report: class it and name the investigator — POST /api/v1/incidents/{incident_id}/review (who may call: holders of incident.manage). */
export function reviewIncidents(incident_id: number, body: IncidentReviewIn): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("POST", `/incidents/${incident_id}/review`, body);
}

/** Withdraw a report that is not an incident — POST /api/v1/incidents/{incident_id}/withdraw (who may call: holders of incident.manage). */
export function withdrawIncidents(incident_id: number, body: WithdrawIn): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("POST", `/incidents/${incident_id}/withdraw`, body);
}

/** Save the analysis (a draft until signed) — PUT /api/v1/incidents/{incident_id}/analysis (who may call: holders of incident.report or incident.manage). */
export function saveAnalysis(incident_id: number, body: AnalysisIn): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("PUT", `/incidents/${incident_id}/analysis`, body);
}

/** Sign the analysis (final) — POST /api/v1/incidents/{incident_id}/analysis/sign (who may call: holders of incident.report or incident.manage). */
export function signAnalysis(incident_id: number, body: IncidentSignIn): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("POST", `/incidents/${incident_id}/analysis/sign`, body);
}

/** Record a corrective or preventive action — POST /api/v1/incidents/{incident_id}/actions (who may call: holders of incident.report or incident.manage). */
export function addActionIncidentsActions(incident_id: number, body: QualityActionIn): Promise<QualityActionOut> {
  return api<QualityActionOut>("POST", `/incidents/${incident_id}/actions`, body, { idempotent: true });
}

/** Close an incident with the follow-up — POST /api/v1/incidents/{incident_id}/close (who may call: holders of incident.manage). */
export function closeIncidents(incident_id: number, body: IncidentCloseIn): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("POST", `/incidents/${incident_id}/close`, body);
}

/** The incident report with its analysis and actions (PDF) — GET /api/v1/incidents/{incident_id}/pdf (who may call: incident.view, the reporter and the investigator; ot.clinical_statistics.view for theatre adverse events). */
export function incidentPdf(incident_id: number): Promise<unknown> {
  return api<unknown>("GET", `/incidents/${incident_id}/pdf`, undefined);
}

